CREATE TABLE runs_new(run_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), scenario_version TEXT NOT NULL, schema_version INTEGER NOT NULL, simulator_version TEXT NOT NULL, seed INTEGER NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('offline','replay','live')), memory_enabled INTEGER NOT NULL, history_days INTEGER NOT NULL, simulation_days INTEGER NOT NULL CHECK(simulation_days BETWEEN 1 AND 7), start_date TEXT NOT NULL, current_day INTEGER NOT NULL, phase TEXT NOT NULL, source_run_id TEXT, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, execution_profile TEXT NOT NULL DEFAULT 'reference', content_mode TEXT NOT NULL DEFAULT 'local', learning_mode TEXT NOT NULL DEFAULT 'skip', initial_snapshot_hash TEXT NOT NULL DEFAULT '', config_json TEXT NOT NULL DEFAULT '{}', created_by TEXT, demo_shop_id TEXT NOT NULL DEFAULT 'D', brief_json TEXT CHECK(brief_json IS NULL OR json_valid(brief_json)), brief_version INTEGER NOT NULL DEFAULT 0);
INSERT INTO runs_new(run_id,session_id,scenario_version,schema_version,simulator_version,seed,mode,memory_enabled,history_days,simulation_days,start_date,current_day,phase,source_run_id,version,created_at,updated_at,execution_profile,content_mode,learning_mode,initial_snapshot_hash,config_json,created_by) SELECT run_id,session_id,scenario_version,4,simulator_version,seed,mode,memory_enabled,history_days,simulation_days,start_date,current_day,phase,source_run_id,version,created_at,updated_at,execution_profile,content_mode,learning_mode,initial_snapshot_hash,config_json,created_by FROM runs;
DROP TABLE runs;
ALTER TABLE runs_new RENAME TO runs;
ALTER TABLE negotiations ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE negotiations ADD COLUMN pinned_context_json TEXT CHECK(pinned_context_json IS NULL OR json_valid(pinned_context_json));
ALTER TABLE negotiations ADD COLUMN pinned_context_hash TEXT;
ALTER TABLE negotiations ADD COLUMN terminal_receipt_json TEXT CHECK(terminal_receipt_json IS NULL OR json_valid(terminal_receipt_json));
ALTER TABLE negotiations ADD COLUMN terminal_hash TEXT;
ALTER TABLE content_jobs ADD COLUMN provider_state_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(provider_state_json));
CREATE TABLE daily_predictions(run_id TEXT NOT NULL, shop_id TEXT NOT NULL, day INTEGER NOT NULL CHECK(day BETWEEN 1 AND 7), prediction_id TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), payload_hash TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(run_id,shop_id,day), UNIQUE(run_id,prediction_id), FOREIGN KEY(run_id,shop_id) REFERENCES shops(run_id,shop_id));
